    background-color: red;
}

.word::after:nth-child(2) {
    left: 40%;
    background-color: green;
}

.word::after:nth-child(3) {
    left: 60%;
    background-color: blue;
}

.word::after:nth-child(4) {
    left: 80%;
    background-color: orange;
}

.word::after:nth-child(5) {
    left: 100%;
    background-color: purple;
}
